insert into public.weekly_schedules (doctor_id, day_of_week, start_time, end_time, is_active)
select d.id, day, d.start_time, d.end_time, true
from (values
  ('33000000-0000-0000-0000-000000000001'::uuid, '09:00'::time, '17:00'::time, array[0, 1, 2, 3, 4]),
  ('33000000-0000-0000-0000-000000000002'::uuid, '12:00'::time, '20:00'::time, array[1, 3, 5]),
  ('33000000-0000-0000-0000-000000000003'::uuid, '08:00'::time, '16:00'::time, array[0, 2, 4]),
  ('33000000-0000-0000-0000-000000000004'::uuid, '10:00'::time, '18:00'::time, array[0, 1, 2, 3, 4, 5, 6]),
  ('33000000-0000-0000-0000-000000000005'::uuid, '09:00'::time, '15:00'::time, array[2, 4, 6]),
  ('33000000-0000-0000-0000-000000000006'::uuid, '11:00'::time, '19:00'::time, array[1, 3, 5])
) as d(id, start_time, end_time, days)
cross join lateral unnest(d.days) as day;

